// ---------------------------------------------------------------- prompt builders

function readerPrompt(u, unitIdx) {
  const partNote = u.n_parts > 1
    ? `This book is split into ${u.n_parts} parts; you are reading PART ${u.part} of ${u.n_parts} (file "${u.path}"). Read every line of your part. Coordinate by reusing the shared strategy_id vocabulary so parts of the same book converge on the same ids.`
    : `You are reading the entire book "${u.title}" (file "${u.path}"). Read every page / every line of the file.`
  const tierNote = u.tier === 'C'
    ? `This is a narrative/biography book. Extract at most 5 findings, focusing on explicit trading/methodology/evidence lessons. If a portion is pure narrative biography, do not force findings from it.`
    : `Extract up to ${u.cap} findings. Prefer strategies that are (a) concretely falsifiable, (b) likely corroborated by other books in this library, (c) mapped to crypto perpetual futures (24/7 market, funding, no exchange gaps, high leverage).`
  return `You are a trading-strategy extraction analyst for the V8 research program.

${V8}

TASK: Deep-read the assigned book text file(s) and extract its strategies, mechanisms, setups, risk rules, and methodology lessons as structured findings. Read the file(s) fully (multiple Read calls; the file is large, read it in full, do not stop early). Do NOT invent content the book does not state; base every finding on actual text.

${partNote}

${tierNote}

Rules:
- One finding per distinct strategy/mechanism. Do not emit near-duplicates of the same strategy from the same book.
- For every finding choose: strategy_class (controlled enum), v8_component (where it lands in V8), v8_action (what V8 should do with it), mechanism_family_candidate + behavior_family_candidate (proposed V8 ids, follow existing naming style: lowercase snake_case, e.g. liquidity_vacuum_reentry), feature_groups_required (from the feature-group vocabulary), direction, applicability_to_perp_crypto (reason about 24/7 crypto perp specifics: no gaps, funding, leverage, venue microstructure - do not default to HIGH), evidence_class (LITERATURE_SUPPORTED if the book makes a falsifiable empirical/statistical case; DESIGN_INFERENCE if practitioner heuristic; NARRATIVE if storytelling), and a short verbatim quote + chapter anchor.
- risk_geometry: note entry type (bar close / limit), stop (ATR multiple / swing point / %), target (R-multiple / structure), expiry (bars) - only what the book states.
- setup_summary must be concrete and falsifiable (what observable conditions, on which timeframe).
- REUSE strategy_id slugs from the starter vocabulary whenever the book's strategy matches. For genuinely new ones, use NEW_<snake_case>.
- Do not editorialize about V8's edge; V8 is evidence-bound.

${STARTER_IDS}

Return the findings in the schema. Max ${u.cap} findings.`
}

function mergePrompt(bucketName, findings, seedFile, jobLabel) {
  const json = JSON.stringify(findings)
  const seedNote = seedFile
    ? `ADDITIONAL INPUT: a file with previously-extracted findings for this theme exists at "${seedFile}". Read that file FULLY (it is a JSON array; each element has a "book" field naming the book, plus the finding fields). Merge those findings into your canonical findings too, with the same dedup rules. Do not drop them.`
    : ''
  return `You are a merge analyst for the V8 research program. Multiple deep-read analysts extracted strategy findings from many trading books. Your bucket (${bucketName}) received ${findings.length} findings extracted from different books (job ${jobLabel}).

${V8}

${seedNote}

TASK: Merge these findings into canonical findings.
- Group findings that describe THE SAME strategy / mechanism across books into ONE canonical finding. Same book appearing twice for one strategy also merges (that happens when a book was split into parts).
- For each canonical finding: pick the best strategy_name (most descriptive), write a merged setup_summary, trigger_invalidation, risk_geometry, feature_groups_required, direction, applicability_to_perp_crypto, evidence_class (upgrade to LITERATURE_SUPPORTED if >=2 independent books make an empirical case; else DESIGN_INFERENCE/NARRATIVE).
- books: list every distinct book with a role: 'primary' (book that defines it best / most detail), 'supports' (corroborates), 'mentions' (brief), 'contrast' (book that argues AGAINST it). Keep at most one short quote from the primary book.
- v8_action: decide what V8 should do. v8_component: where it lands.
- Drop or mark REJECT_FOR_V8 findings that are not usable in V8 (e.g. equity-only fundamentals with no crypto analogue, astrology/timing nonsense, binary options scam content, pure discretionary floor chatter) - but keep methodology and risk lessons even from weak books.
- IMPORTANT: no duplicate canonical findings within your bucket. A canonical finding must represent one distinct strategy/mechanism.
- Do not invent corroboration: only list books that actually appear in your input findings.
- Return at most 45 canonical findings, best first (highest V8 value).`

}

function finalPrompt(merged, coverage, units) {
  const json = JSON.stringify(merged)
  const cov = JSON.stringify(coverage)
  return `You are the final synthesis analyst for the V8 research program. Mergers across 8 theme buckets produced canonical findings from ~125 trading books read deeply.

${V8}

INPUT A (merged canonical findings, JSON): ${json}
INPUT B (per-book coverage, JSON): ${cov}
INPUT C (book inventory): ${units.map(u => u.title).join('; ')}

TASK: Produce the final V8 register.
1. canonical_findings: dedupe ACROSS buckets (the same strategy may appear in two theme buckets). Each final finding: canonical_id, strategy_name, strategy_class, mechanism, v8_component, v8_action, direction, merged setup_summary / trigger_invalidation / risk_geometry / feature_groups_required, applicability_to_perp_crypto, evidence_class, books[] (title+role), priority (HIGH/MEDIUM/LOW for V8 value), notes. Sort by priority (HIGH first). Aim for a comprehensive but deduplicated register - typically 120-180 findings; do not artificially inflate or truncate.
2. v8_recommendations: structured proposals.
   - propose_new_expert: concrete new expert families (mechanism_family_id, behavior_family_id, variant_id 'a', requires[], direction, rationale, supporting book titles, priority). Follow EXPERT_PROTOCOL ontology. Respect rule 14 complexity budget: only recommend the top 3-5 to actually build, mark the rest DEFER.
   - refine_existing: for trend_pullback / failed_breakout / liquidity_sweep_reclaim - specific parameter/geometry/still_valid refinements books support, with book citations.
   - backlog_candidate: breakout_retest / capitulation support from books, plus any other families that should be registry entries (status DATA_BLOCKED if derivatives data needed).
   - feature_inputs: specific MarketState feature suggestions (e.g. funding_rate, basis, open_interest, volume_delta, session_volume_profile, position_skew, cot-like positioning proxy, realized vol, etc.) with group + rationale + books.
   - risk_rules: risk/position-sizing rules (ATR stop multiples, R-based sizing, max risk per trade, correlated exposure caps, drawdown circuit breakers) with books.
   - lifecycle_rules: episode-management rules (time stops, break-even management, pyramiding limits, thesis invalidation) with books.
   - regime_filters: market-regime filters books recommend (trend/range detection, volatility regime, time-of-day) with books.
   - simulator_models: execution/microstructure cost models (slippage, order book impact, funding settlement) with books.
   - methodology_lessons: evidence standards, backtest hygiene, multiple-testing, luck-vs-skill (Fooled by Randomness / Evidence-Based TA / Building Reliable Trading Systems) - these are LITERATURE_SUPPORTED inputs to the program's evidence culture.
   - deferred_gated: router/scorer/ranker/learned-execution inputs (only post-gate).
   - rejected_counts: summarize how many were rejected and why.
3. multi_book_corroboration: list canonical findings ordered by number of distinct books (>=2), with titles. This is the dedup + corroboration evidence.
4. gaps: strategies the library does NOT cover that V8 cares about (e.g. crypto-native funding/liquidation mechanics, intraday HFT microstructure).
5. warnings: honest caveats (books are equity/forex/futures-centric; most are pre-crypto; none are peer-reviewed; OCR noise in scanned books; narrative books analyzed at lower density).
6. per_book_coverage: keep INPUT B, but annotate the top-1 v8_action per book.`
}

// ---------------------------------------------------------------- helpers

function shortLabel(u) {
  const base = u.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 28)
  return u.n_parts > 1 ? `${base}~${u.part}` : base
}

function bucketOf(f) {
  const s = (f.strategy_class || '') + ' ' + (f.mechanism || '') + ' ' + (f.strategy_id || '') + ' ' + (f.behavior_family_candidate || '')
  const sL = s.toLowerCase()
  if (/liquidity|sweep|stop hunt|order flow|microstructure|maker|taker|impact|execution|auction|flash crash|deleverag|iceberg|spoofing|bid.ask|gamma|market maker/.test(sL)) return 'liquidity_microstructure'
  if (/trend|momentum|moving average|breakout|pullback|continuation|channel|turtle|dual momentum|donchian/.test(sL)) return 'trend_momentum'
  if (/reversion|range|oscillat|rsi|stochastic|overbought|oversold|mean|pivot|band/.test(sL)) return 'mean_reversion'
  if (/candlestick|engulf|hammer|doji|pattern|harmonic|fibonacci|ichimoku|chart pattern|three soldier|morning star/.test(sL)) return 'pattern_candlestick'
  if (/volume|vwap|profile|delta|obv|accumulation|distribution|poc/.test(sL)) return 'volume_flow'
  if (/volatil|atr|bollinger|expansion|contraction|compression|gamma|climax/.test(sL)) return 'volatility'
  if (/intermarket|correlation|sentiment|cot|positioning|carry|funding|basis|macro|sector|seasonal|rotation|time of day|session/.test(sL)) return 'cross_market_sentiment'
  if (/risk|position sizing|money management|stop|psycholog|discipline|expectancy|edge|evidence|backtest|overfitt|methodolog|survival|drawdown|kelly/.test(sL)) return 'risk_psych_methodology'
  return 'other'
}

function partitionByTheme(findings) {
  const buckets = {}
  for (const f of findings) {
    const b = bucketOf(f)
    ;(buckets[b] = buckets[b] || []).push(f)
  }
  return buckets
}

