// ---------------------------------------------------------------- phases

phase('Read')
const units = (args && args.units) || UNITS
const readResults = await parallel(units.map(u => () =>
  agent(readerPrompt(u), { label: `read:${shortLabel(u)}`, phase: 'Read', schema: FINDINGS_SCHEMA, effort: 'high' })
    .then(r => (r && Array.isArray(r.findings)) ? r.findings.map(f => ({ ...f, book: u.title })) : null)))

const okResults = readResults.filter(Boolean)
const allFindings = okResults.flat()

// per-book coverage: new reads + pre-seeded counts (SEED_COUNTS embedded by generator)
const byTitle = {}
for (const f of allFindings) {
  const t = f.book || '?'
  byTitle[t] = byTitle[t] || { n: 0, actions: {} }
  byTitle[t].n++
  byTitle[t].actions[f.v8_action] = (byTitle[t].actions[f.v8_action] || 0) + 1
}
for (const [t, n] of Object.entries((typeof SEED_COUNTS !== 'undefined') ? SEED_COUNTS : {})) {
  byTitle[t] = byTitle[t] || { n: 0, actions: {} }
  byTitle[t].n += n
}
const coverage = units.map(u => ({ title: u.title, n_findings: (byTitle[u.title] || {}).n || 0, top_actions: (byTitle[u.title] || {}).actions || {} }))

log(`read done: ${okResults.length} chunks, ${allFindings.length} new findings from ${units.length} units`)

phase('Merge')
// One merge job per bucket; buckets with pre-seeded findings (on disk) get one job per
// seed chunk file, and the merge agent reads that file itself.
const newBuckets = partitionByTheme(allFindings)
const seedChunks = (typeof SEED_CHUNKS !== 'undefined') ? SEED_CHUNKS : {}
const allBucketNames = [...new Set([...Object.keys(newBuckets), ...Object.keys(seedChunks)])].sort()
const mergeJobs = []
for (const bn of allBucketNames) {
  const chunks = seedChunks[bn] || []
  const newFs = newBuckets[bn] || []
  if (chunks.length === 0) {
    if (newFs.length > 0) mergeJobs.push({ label: `merge:${bn}`, bucket: bn, findings: newFs, seedFile: null })
  } else {
    const per = Math.max(1, Math.ceil(newFs.length / chunks.length))
    chunks.forEach((cf, ci) => {
      mergeJobs.push({ label: `merge:${bn}#${ci + 1}`, bucket: bn, findings: newFs.slice(ci * per, ci * per + per), seedFile: cf })
    })
  }
}
const merged = await parallel(mergeJobs.map(j => () =>
  agent(mergePrompt(j.bucket, j.findings, j.seedFile, j.label), { label: j.label, phase: 'Merge', schema: MERGE_SCHEMA, effort: 'high' })))

const mergedFindings = merged.filter(Boolean).flatMap(m => m.canonical_findings || [])
log(`merge done: ${mergeJobs.length} jobs, ${mergedFindings.length} canonical findings`)

phase('Synthesize')
const final = await agent(finalPrompt(mergedFindings, coverage, units),
  { label: 'synthesize', phase: 'Synthesize', schema: FINAL_SCHEMA, effort: 'xhigh' })

return final
